std::string expr = FUZZ_PARAM_STR();
const char *c_expr = expr.c_str();
// Randomly decide whether to request error details or not.
bool want_err = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
int err_storage = 0;
int *err_ptr = want_err ? &err_storage : nullptr;
// Evaluate one-shot. The function may return NaN on error; that is acceptable for fuzzing.
volatile double result = te_interp(c_expr, err_ptr);
(void)result;
// Validation: Inputs are valid pointers, error storage is writable when provided. No persistent objects to output.
// Validation summary: te_interp exercised with/without error pointer; expression is a valid C string pointer.

// Prepare an expression string.
std::string expr = FUZZ_PARAM_STR();
const char *c_expr = expr.c_str();
// Choose a small variable count to keep allocations bounded.
unsigned int raw = *FUZZ_PARAM(unsigned int);
int var_count = (int)(raw % 5); // 0..4
// Randomly decide whether to pass an error pointer.
bool want_err = ((raw >> 3) & 1u) != 0u;
int err_storage = 0;
int *err_ptr = want_err ? &err_storage : nullptr;
// Build a variable table if var_count > 0. For TE_VARIABLE bindings, address must outlive te_eval.
// We allocate a persistent heap buffer for the variable values and attach it to the te_expr via attributes.
std::vector<std::string> names; // keep name storage alive during te_compile
names.reserve((size_t)var_count);
// Allocate values buffer on heap so it can outlive this stub; freed in te_free stub.
double *vals = nullptr;
te_variable *vars = nullptr;
if (var_count > 0) {
    vals = new double[(size_t)var_count];
    // Fill values with random doubles.
    for (int i = 0; i < var_count; ++i) {
        // Compose a double from two random 32-bit parts; scale to keep finite.
        unsigned long long hi = (unsigned long long)(*FUZZ_PARAM(unsigned int));
        unsigned long long lo = (unsigned long long)(*FUZZ_PARAM(unsigned int));
        unsigned long long bits = (hi << 32) ^ lo;
        double v = (double)((long long)(bits % 1000003) - 500000); // keep magnitude moderate
        vals[i] = v;
    }
    // Build te_variable array (stack allocated small vector then pointer stable during call)
    // We'll allocate it on a small heap block to simplify lifetime if needed elsewhere, but it is only needed for compile.
    vars = (te_variable*)::operator new[](sizeof(te_variable) * (size_t)var_count);
    for (int i = 0; i < var_count; ++i) {
        names.emplace_back(FUZZ_PARAM_STR());
        te_variable tv{};
        tv.name = names.back().c_str();
        tv.address = (const void*)&vals[i]; // address of a double for TE_VARIABLE
        tv.type = TE_VARIABLE; // plain variable binding
        tv.context = nullptr;
        vars[i] = tv;
    }
}
// Compile the expression.
te_expr *n = te_compile(c_expr, vars, var_count, err_ptr);
// Release temporary te_variable storage; the library does not retain this array.
if (vars) { ::operator delete[](vars); }
// If compilation failed, bail without returning an output.
if (!n) {
    // Clean up persistent vals if we allocated them; they won't be needed without a compiled expression.
    if (vals) { delete[] vals; }
    FUZZ_BAIL();
}
// Attach attributes so downstream stubs (eval/print/free) can manage lifetime of bound variable addresses.
FUZZ_SET_ATTR_PTR(n, "vars_buf", (void*)vals);
FUZZ_SET_ATTR_INT(n, "var_count", var_count);
// Note: vals may be null when var_count == 0; that's acceptable and tracked.
// Output: return the compiled expression to the pool.
// Validation summary: Ensures var_count >= 0, passes either NULL or a writable error pointer, and guarantees bound variable storage persists by attaching it to the te_expr for later cleanup.

// Ensure this te_expr came from our te_compile stub by checking attached attributes.
int var_count = FUZZ_GET_ATTR_INT(n, "var_count");
void *vars_buf = FUZZ_GET_ATTR_PTR(n, "vars_buf");
if (var_count < 0) { FUZZ_BAIL(); }
if (var_count == 0 && vars_buf != nullptr) { FUZZ_BAIL(); }
if (var_count > 0 && vars_buf == nullptr) { FUZZ_BAIL(); }
// Evaluate the expression; result may be NaN and that's acceptable for fuzzing.
volatile double result = te_eval(n);
(void)result;
// Return the expression to the pool for further operations (e.g., print or free).
// Validation summary: Accepts only valid compiled te_expr with persistent bound variables; does not consume ownership.

// Validate attributes to ensure 'n' is a live compiled expression created by te_compile stub.
int var_count = FUZZ_GET_ATTR_INT(n, "var_count");
void *vars_buf = FUZZ_GET_ATTR_PTR(n, "vars_buf");
if (var_count < 0) { FUZZ_BAIL(); }
if (var_count == 0 && vars_buf != nullptr) { FUZZ_BAIL(); }
if (var_count > 0 && vars_buf == nullptr) { FUZZ_BAIL(); }
// Print the syntax tree for diagnostic coverage.
te_print(n);
// Keep the expression alive for subsequent stubs.
// Validation summary: Only prints expressions confirmed to be valid and unfrozen; does not alter ownership.

// te_free is safe with NULL.
if (n) {
    // If this te_expr was created by our te_compile stub, free the attached variable buffer.
    int var_count = FUZZ_GET_ATTR_INT(n, "var_count");
    void *vars_buf = FUZZ_GET_ATTR_PTR(n, "vars_buf");
    if (var_count > 0 && vars_buf) {
        delete[] (double*)vars_buf;
        // Clear attributes (optional in this harness; object will be freed next).
        FUZZ_SET_ATTR_INT(n, "var_count", 0);
        FUZZ_SET_ATTR_PTR(n, "vars_buf", nullptr);
    }
}
// Free the compiled expression itself.
te_free(n);
// Do not return any outputs; ownership is released.
// Validation summary: Safely handles NULL, cleans up any heap-allocated bound variable storage, and avoids use-after-free by not returning the object.

