import random
from typing import List

MAX_LEN = 1024

UNARY_FUNCS = [
    "abs", "acos", "asin", "atan", "ceil", "cos", "cosh", "deg",
    "exp", "floor", "log", "log10", "rad", "sin", "sinh", "sqrt",
    "tan", "tanh", "not"
]
BINARY_FUNCS = [
    "atan2", "min", "max", "pow"
]
TERNARY_FUNCS = [
    "if"
]
UNARY_OPS = ["+", "-", "!"]
BINARY_OPS = ["+", "-", "*", "/", "%", "^"]
DEFAULT_VARS = ["x", "y", "z", "a", "b", "c", "t", "u", "v"]
WHITES = [" ", "\t", "\n", ""]

MAX_DEPTH = 6


def rnd(rng: random.Random, seq):
    # Safe random chooser without recursion
    return seq[rng.randrange(len(seq))]


def maybe_ws(rng: random.Random) -> str:
    # Bounded, tiny whitespace
    n = rng.randrange(0, 3)
    out = []
    for _ in range(n):
        out.append(rnd(rng, WHITES))
    return "".join(out)


def gen_number(rng: random.Random) -> str:
    kind = rng.randrange(6)
    if kind == 0:
        return str(rng.randrange(0, 10 ** rng.randrange(1, 7)))
    if kind == 1:
        intp = str(rng.randrange(0, 10 ** rng.randrange(1, 5)))
        frac_len = rng.randrange(1, 6)
        frac_val = rng.randrange(0, 10 ** frac_len)
        frac = str(frac_val).rjust(frac_len, "0")
        return intp + "." + frac
    if kind == 2:
        frac_len = rng.randrange(1, 6)
        frac_val = rng.randrange(0, 10 ** frac_len)
        frac = str(frac_val).rjust(frac_len, "0")
        return "." + frac
    if kind == 3:
        # scientific notation
        base = str(rng.uniform(-1e3, 1e3))
        sign = rnd(rng, ["+", "-", ""])  # optional sign
        exp = rng.randrange(0, 13)
        return f"{base}e{sign}{exp}"
    if kind == 4:
        return rnd(rng, ["pi", "e"])  # constants supported by TinyExpr
    return str(rng.uniform(-1e6, 1e6))


def gen_var(rng: random.Random) -> str:
    if rng.random() < 0.8:
        return rnd(rng, DEFAULT_VARS)
    first = rnd(rng, list("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"))
    rest = "".join(rnd(rng, list("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789"))
                    for _ in range(rng.randrange(0, 4)))
    return first + rest


def gen_atom(rng: random.Random, depth: int) -> str:
    # Base atom that doesn't recurse further at max depth
    if depth >= MAX_DEPTH:
        return rnd(rng, [gen_number(rng), gen_var(rng)])
    choice = rng.random()
    if choice < 0.5:
        return gen_number(rng)
    if choice < 0.8:
        return gen_var(rng)
    # Parenthesized simple non-recursive or shallow expression to avoid deep chains
    inner = gen_simple(rng, depth + 1)
    return "(" + maybe_ws(rng) + inner + maybe_ws(rng) + ")"


def gen_unary(rng: random.Random, depth: int) -> str:
    if depth >= MAX_DEPTH:
        # stop chaining, return atom
        return gen_atom(rng, depth)
    if rng.random() < 0.5:
        # limit chain length explicitly
        times = 1 + rng.randrange(2)
        ops = "".join(rnd(rng, UNARY_OPS) for _ in range(times))
        return ops + maybe_ws(rng) + gen_atom(rng, depth + 1)
    # unary function
    fname = rnd(rng, UNARY_FUNCS)
    arg = gen_simple(rng, depth + 1)
    return f"{fname}{maybe_ws(rng)}(" + maybe_ws(rng) + arg + maybe_ws(rng) + ")"


def gen_term(rng: random.Random, depth: int) -> str:
    if rng.random() < 0.5:
        return gen_atom(rng, depth)
    return gen_unary(rng, depth)


def gen_bin_chain(rng: random.Random, depth: int, min_terms=2, max_terms=4) -> str:
    # Avoid building chains at excessive depth
    if depth >= MAX_DEPTH:
        return gen_term(rng, depth)
    count = rng.randrange(min_terms, max_terms + 1)
    terms = [gen_term(rng, depth + 1) for _ in range(count)]
    s = terms[0]
    for t in terms[1:]:
        op = rnd(rng, BINARY_OPS)
        s = s + maybe_ws(rng) + op + maybe_ws(rng) + t
    return s


def gen_call_with_args(rng: random.Random, depth: int) -> str:
    if depth >= MAX_DEPTH:
        # degrade to unary to avoid further recursion
        return gen_unary(rng, depth)
    roll = rng.random()
    if roll < 0.6:
        fname = rnd(rng, UNARY_FUNCS)
        args = [gen_simple(rng, depth + 1)]
    elif roll < 0.9:
        fname = rnd(rng, BINARY_FUNCS)
        args = [gen_simple(rng, depth + 1), gen_simple(rng, depth + 1)]
    else:
        fname = rnd(rng, TERNARY_FUNCS)
        cond = gen_simple(rng, depth + 1)
        args = [cond, gen_simple(rng, depth + 1), gen_simple(rng, depth + 1)]
    return f"{fname}{maybe_ws(rng)}(" + ",".join(maybe_ws(rng) + a + maybe_ws(rng) for a in args) + ")"


def gen_simple(rng: random.Random, depth: int) -> str:
    # Simpler expression builder that keeps recursion shallow
    if depth >= MAX_DEPTH:
        return gen_atom(rng, depth)
    p = rng.random()
    if p < 0.4:
        return gen_term(rng, depth)
    if p < 0.7:
        return gen_bin_chain(rng, depth, 2, 3)
    return gen_call_with_args(rng, depth)


def gen_expr(rng: random.Random, depth: int = 0) -> str:
    if depth >= MAX_DEPTH:
        return gen_atom(rng, depth)
    p = rng.random()
    if p < 0.3:
        return gen_term(rng, depth)
    if p < 0.6:
        return gen_bin_chain(rng, depth, 2, 4)
    if p < 0.85:
        return gen_call_with_args(rng, depth)
    left = gen_call_with_args(rng, depth + 1)
    right = gen_term(rng, depth + 1)
    op = rnd(rng, BINARY_OPS)
    return left + maybe_ws(rng) + op + maybe_ws(rng) + right


def ensure_vars_presence(rng: random.Random, expr: str) -> str:
    if rng.random() < 0.6:
        k = rng.randrange(1, 3)
        parts = []
        for _ in range(k):
            coef = gen_number(rng)
            v = gen_var(rng)
            parts.append(f"{coef}{maybe_ws(rng)}*{maybe_ws(rng)}{v}")
        combined = (f" {rnd(rng, ['+', '-'])} ").join(parts)
        expr = combined + f" {rnd(rng, ['+', '-', '*'])} " + expr
    return expr


def clamp_len(s: str) -> str:
    return s[:MAX_LEN] if len(s) > MAX_LEN else s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    strat = rng.randrange(5)
    if strat == 0:
        expr = gen_expr(rng, 0)
    elif strat == 1:
        terms = [gen_call_with_args(rng, 0) for _ in range(1 + rng.randrange(4))]
        expr = (" + ").join(terms)
    elif strat == 2:
        inner = gen_bin_chain(rng, 0, 3, 5)
        wraps = rng.randrange(1, 4)
        expr = inner
        for _ in range(wraps):
            # short unary prefix only, avoid recursive unary chaining
            uops = "".join(rnd(rng, UNARY_OPS) for _ in range(1))
            expr = uops + "(" + maybe_ws(rng) + expr + maybe_ws(rng) + ")"
    elif strat == 3:
        chain_len = 2 + rng.randrange(3)
        arg = gen_var(rng)
        for _ in range(chain_len):
            if rng.random() < 0.7:
                fname = rnd(rng, UNARY_FUNCS)
                arg = f"{fname}({arg})"
            else:
                fname = rnd(rng, BINARY_FUNCS)
                arg = f"{fname}({arg},{gen_number(rng)})"
        tail = gen_bin_chain(rng, 0, 2, 3)
        expr = arg + " + " + tail
    else:
        parts = []
        n_terms = 3 + rng.randrange(4)
        for _ in range(n_terms):
            term = gen_term(rng, 0)
            if rng.random() < 0.4:
                term = term + maybe_ws(rng) + "^" + maybe_ws(rng) + gen_term(rng, 1)
            if rng.random() < 0.3:
                term = "(" + term + ")"
            parts.append(term)
        expr = (" % ").join(parts) if rng.random() < 0.5 else (" * ").join(parts)

    expr = ensure_vars_presence(rng, expr)
    expr = clamp_len(expr)
    return expr.encode("utf-8")

import random
import string
from typing import List

# Robust TinyExpr input generator with strict recursion/depth limits to avoid stack overflows.
# Produces a blob of NUL-terminated C strings: expr\0name0\0...\0

IDENT_START = string.ascii_letters + "_"
IDENT_BODY = string.ascii_letters + string.digits + "_"

FUNCTIONS_UNARY = [
    "sin", "cos", "tan", "sqrt", "log", "log10", "abs", "floor", "ceil"
]
FUNCTIONS_BINARY = [
    "min", "max", "pow"
]

BIN_OPS = ["+", "-", "*", "/", "^"]

MAX_TOTAL_BYTES = 4096
MAX_EXPR_DEPTH = 4  # hard cap for recursion


def rand_ident(rng: random.Random, used: set) -> str:
    for _ in range(100):
        n = rng.randint(1, 10)
        s = rng.choice(IDENT_START) + "".join(rng.choice(IDENT_BODY) for _ in range(n - 1))
        if s not in used:
            used.add(s)
            return s
    base = rng.choice(IDENT_START)
    suffix = str(rng.randrange(1_000_000))
    s = base + suffix
    used.add(s)
    return s


def rand_number(rng: random.Random) -> str:
    choice = rng.randrange(6)
    if choice == 0:
        return str(rng.randint(-1000, 1000))
    if choice == 1:
        return f"{rng.uniform(-1000, 1000):.6f}"
    if choice == 2:
        return f"{rng.uniform(-10, 10):.6g}"
    if choice == 3:
        base = rng.uniform(-10, 10)
        exp = rng.randint(-5, 5)
        return f"{base:.6g}e{exp:+d}"
    if choice == 4:
        return f"{rng.choice([0.5, 1.0, 2.0, 3.0, 10.0])}"
    return str(rng.randint(-8, 8))


def maybe_unary(rng: random.Random, expr: str) -> str:
    if rng.random() < 0.3:
        return rng.choice(["+", "-"]) + expr
    return expr


def gen_atom(rng: random.Random, vars_pool: List[str], depth: int) -> str:
    # Base termination: if depth limit reached, avoid recursion via functions
    if depth >= MAX_EXPR_DEPTH:
        if vars_pool and rng.random() < 0.5:
            return rng.choice(vars_pool)
        return maybe_unary(rng, rand_number(rng))

    t = rng.random()
    if t < 0.35 and vars_pool:
        return rng.choice(vars_pool)
    if t < 0.7:
        return maybe_unary(rng, rand_number(rng))
    # Unary function (bounded by depth)
    f = rng.choice(FUNCTIONS_UNARY)
    inner = gen_expr(rng, vars_pool, depth + 1)
    return f"{f}({inner})"


def gen_binary_func(rng: random.Random, vars_pool: List[str], depth: int) -> str:
    # If depth cap reached, fallback to atoms to terminate
    if depth >= MAX_EXPR_DEPTH:
        return gen_atom(rng, vars_pool, depth)
    f = rng.choice(FUNCTIONS_BINARY)
    a = gen_expr(rng, vars_pool, depth + 1)
    if f == "pow":
        if rng.random() < 0.7:
            b = str(rng.randint(-5, 5))
        else:
            b = gen_expr(rng, vars_pool, depth + 1)
    else:
        b = gen_expr(rng, vars_pool, depth + 1)
    return f"{f}({a},{b})"


def gen_term(rng: random.Random, vars_pool: List[str], depth: int) -> str:
    if depth >= MAX_EXPR_DEPTH:
        return gen_atom(rng, vars_pool, depth)
    x = rng.random()
    if x < 0.2:
        inner = gen_expr(rng, vars_pool, depth + 1)
        return f"({inner})"
    if x < 0.35:
        return gen_binary_func(rng, vars_pool, depth + 1)
    return gen_atom(rng, vars_pool, depth)


def gen_expr(rng: random.Random, vars_pool: List[str], depth: int = 0) -> str:
    if depth >= MAX_EXPR_DEPTH:
        return gen_atom(rng, vars_pool, depth)
    parts = [gen_term(rng, vars_pool, depth)]
    max_ops = 3 if depth == 0 else 2
    ops = rng.randint(0, max_ops)
    for _ in range(ops):
        op = rng.choice(BIN_OPS)
        if op == "/" and rng.random() < 0.5:
            denom = gen_term(rng, vars_pool, depth + 1)
            eps = rng.choice(["0.1", "1", "1e-3"]) if rng.random() < 0.7 else rand_number(rng)
            right = f"(abs({denom})+{eps})"
        else:
            right = gen_term(rng, vars_pool, depth + 1)
        parts.append(op)
        parts.append(right)
    s = " ".join(parts)
    if depth == 0:
        s = maybe_unary(rng, s)
    return s


def build_expression_with_vars(rng: random.Random, var_names: List[str]) -> str:
    pool = list(var_names)
    terms: List[str] = []
    # Ensure each variable appears at least once with bounded constructs
    for v in pool:
        choice = rng.random()
        if choice < 0.4:
            terms.append(v)
        elif choice < 0.7:
            terms.append(f"sin({v})")
        else:
            terms.append(f"pow({v},{rng.randint(2,4)})")
    # Add a few random bounded subexpressions
    extra = rng.randint(1, 2)
    for _ in range(extra):
        terms.append(gen_expr(rng, pool, depth=0))
    rng.shuffle(terms)
    # Combine with binary ops in a left-fold to limit nesting
    expr = terms[0]
    for t in terms[1:]:
        op = rng.choice(BIN_OPS)
        expr = f"({expr}) {op} ({t})"
    if rng.random() < 0.4:
        expr = f"abs({expr})" if rng.random() < 0.6 else f"sqrt(({expr})*({expr})+1)"
    return expr


def assemble_strings(strings: List[str]) -> bytes:
    data = b"".join((s.encode("utf-8") + b"\x00") for s in strings)
    return data[:MAX_TOTAL_BYTES]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    used = set()

    var_count = rng.randint(0, 4)
    var_names = [rand_ident(rng, used) for _ in range(var_count)]

    if var_count == 0:
        expr = gen_expr(rng, [], depth=0)
    else:
        expr = build_expression_with_vars(rng, var_names)

    if not expr or len(expr) > 3500:
        expr = "0"

    strings = [expr] + var_names
    blob = assemble_strings(strings)
    if not blob.endswith(b"\x00"):
        blob += b"\x00"
    return blob
